interface ExtendedToggleEvent extends Event {
  newState: 'open' | 'closed';
  oldState: 'open' | 'closed';
}

const POPOVER_MOCK_APPLIED = Symbol.for('__popoverMockApplied__');
const ORIGINAL_MATCHES = Symbol.for('__originalMatches__');

export function mockPopoverAPI(): void {
  if ((globalThis as Record<symbol, boolean>)[POPOVER_MOCK_APPLIED]) {
    return;
  }
  (globalThis as Record<symbol, boolean>)[POPOVER_MOCK_APPLIED] = true;

  const originalMatches =
    (globalThis as Record<symbol, typeof HTMLElement.prototype.matches>)[ORIGINAL_MATCHES] ||
    HTMLElement.prototype.matches;
  (globalThis as Record<symbol, typeof HTMLElement.prototype.matches>)[ORIGINAL_MATCHES] =
    originalMatches;

  Object.defineProperty(window, 'requestAnimationFrame', {
    configurable: true,
    enumerable: true,
    writable: true,
    value(cb: FrameRequestCallback): number {
      cb(0);
      return 0;
    },
  });

  const popoverStates = new WeakMap<
    HTMLElement,
    {
      isOpen: boolean;
      popoverValue: string | null;
      triggerElement: HTMLElement | null;
      position: { x: number; y: number };
    }
  >();

  const getPopoverState = (
    element: HTMLElement,
  ): {
    isOpen: boolean;
    popoverValue: string | null;
    triggerElement: HTMLElement | null;
    position: { x: number; y: number };
  } => {
    if (!popoverStates.has(element)) {
      popoverStates.set(element, {
        isOpen: false,
        popoverValue: null,
        triggerElement: null,
        position: { x: 0, y: 0 },
      });
    }
    return popoverStates.get(element) as {
      isOpen: boolean;
      popoverValue: string | null;
      triggerElement: HTMLElement | null;
      position: { x: number; y: number };
    };
  };

  const findTriggerElement = (popoverId: string): HTMLElement | null => {
    return document.querySelector(`[popovertarget="${popoverId}"]`) as HTMLElement;
  };

  const dispatchEventWithDelay = (element: HTMLElement, event: Event, delay = 0): void => {
    if (delay > 0) {
      setTimeout(() => element.dispatchEvent(event), delay);
    } else {
      element.dispatchEvent(event);
    }
  };

  Object.defineProperty(HTMLElement.prototype, 'popover', {
    configurable: true,
    enumerable: true,
    get() {
      const state = getPopoverState(this);
      return state.popoverValue;
    },
    set(value: string | null) {
      const state = getPopoverState(this);
      state.popoverValue = value;

      if (value) {
        this.setAttribute('popover', value);
      } else {
        this.removeAttribute('popover');
      }
    },
  });

  Object.defineProperty(HTMLElement.prototype, 'showPopover', {
    configurable: true,
    enumerable: true,
    writable: true,
    value() {
      const state = getPopoverState(this);

      if (state.isOpen) {
        return;
      }

      const beforeToggleEvent = new Event('beforetoggle', {
        bubbles: true,
        cancelable: true,
      }) as ExtendedToggleEvent;
      beforeToggleEvent.newState = 'open';
      beforeToggleEvent.oldState = 'closed';

      this.dispatchEvent(beforeToggleEvent);

      if (beforeToggleEvent.defaultPrevented) {
        return;
      }

      state.isOpen = true;
      this.style.display = 'block';
      this.style.position = 'absolute';
      this.setAttribute('popover-open', '');

      if (state.position.x === 0 && state.position.y === 0) {
        const rect = this.getBoundingClientRect();
        state.position.x = rect.left;
        state.position.y = rect.top;
      }

      const popoverId = this.getAttribute('id');
      if (popoverId) {
        state.triggerElement = findTriggerElement(popoverId);
      }

      const showEvent = new Event('show', { bubbles: true });
      dispatchEventWithDelay(this, showEvent, 0);
    },
  });

  Object.defineProperty(HTMLElement.prototype, 'hidePopover', {
    configurable: true,
    enumerable: true,
    writable: true,
    value() {
      const state = getPopoverState(this);

      if (!state.isOpen) {
        return;
      }

      const beforeToggleEvent = new Event('beforetoggle', {
        bubbles: true,
        cancelable: true,
      }) as ExtendedToggleEvent;
      beforeToggleEvent.newState = 'closed';
      beforeToggleEvent.oldState = 'open';

      this.dispatchEvent(beforeToggleEvent);

      if (beforeToggleEvent.defaultPrevented) {
        return;
      }

      state.isOpen = false;
      this.removeAttribute('popover-open');

      const hideEvent = new Event('hide', { bubbles: true });
      dispatchEventWithDelay(this, hideEvent, 0);
    },
  });

  Object.defineProperty(HTMLElement.prototype, 'togglePopover', {
    configurable: true,
    enumerable: true,
    writable: true,
    value(force?: boolean) {
      const state = getPopoverState(this);

      if (force === undefined) {
        if (state.isOpen) {
          this.hidePopover();
        } else {
          this.showPopover();
        }
      } else if (force) {
        this.showPopover();
      } else {
        this.hidePopover();
      }
    },
  });

  Object.defineProperty(HTMLElement.prototype, 'matches', {
    configurable: true,
    enumerable: true,
    writable: true,
    value(selector: string) {
      if (selector === ':popover-open') {
        const state = getPopoverState(this);
        return state.isOpen;
      }
      return originalMatches.call(this, selector);
    },
  });
}
