import { dispatchFakeEvent } from './dispatch-events';

function triggerFocusChange(element: HTMLElement, event: 'focus' | 'blur'): void {
  let eventFired = false;
  const handler = (): boolean => (eventFired = true);
  element.addEventListener(event, handler);
  element[event]();
  element.removeEventListener(event, handler);
  if (!eventFired) {
    dispatchFakeEvent(element, event);
  }
}

/**
 * Patches an elements focus and blur methods to emit events consistently and predictably.
 * This is necessary, because some browsers can call the focus handlers asynchronously,
 * while others won't fire them at all if the browser window is not focused.
 * @docs-private
 */
// where browser is not necessarily focused.
export function patchElementFocus(element: HTMLElement): void {
  element.focus = (): Event => dispatchFakeEvent(element, 'focus');
  element.blur = (): Event => dispatchFakeEvent(element, 'blur');
}

/** @docs-private */
export function triggerFocus(element: HTMLElement): void {
  triggerFocusChange(element, 'focus');
}

/** @docs-private */
export function triggerBlur(element: HTMLElement): void {
  triggerFocusChange(element, 'blur');
}
